360:         {
361:             if (expr.Kind == BoundKind.Conversion)
362:             {
363:                 BoundConversion conv = (BoundConversion)expr;
364:                 if (conv.ConversionKind == ConversionKind.Boxing)
365:                 {
366:                     BoundExpression operand = conv.Operand;
367:                     if (operand != null)
368:                     {
369:                         // Is the expression a literal char?  If so, we can
370:                         // simply make it a literal string instead and avoid any 
371:                         // allocations for converting the char to a string at run time.
372:                         if (operand.Kind == BoundKind.Literal)
373:                         {
374:                             ConstantValue cv = ((BoundLiteral)operand).ConstantValue;
375:                             if (cv != null && cv.SpecialType == SpecialType.System_Char)
376:                             {
377:                                 return _factory.StringLiteral(cv.CharValue.ToString());
378:                             }
379:                         }
380: 
381:                         // Can the expression be optimized with a ToString call?
382:                         // If so, we can synthesize a ToString call to avoid boxing.
383:                         if (ConcatExprCanBeOptimizedWithToString(operand.Type))
384:                         {
385:                             var toString = GetSpecialTypeMethod(syntax, SpecialMember.System_Object__ToString);
386:                             return BoundCall.Synthesized(syntax, operand, toString);
387:                         }
388:                     }
389:                 }
390:             }
391: 
392:             // Optimization not possible; just return the original expression.
393:             return expr;
394:         }
