2122:         private LocalDefinition EmitAssignmentDuplication(BoundAssignmentOperator assignmentOperator, bool used, bool lhsUsesStack)
2123:         {
2124:             LocalDefinition temp = null;
2125:             if (used)
2126:             {
2127:                 _builder.EmitOpCode(ILOpCode.Dup);
2128: 
2129:                 if (lhsUsesStack)
2130:                 {
2131:                     // Today we sometimes have a case where we assign a ref directly to a temporary of ref type:
2132:                     //
2133:                     // ref int addr = ref N().y;  <-- copies the address by value; no indirection
2134:                     // int sum = addr + 10;
2135:                     // addr = sum;
2136:                     //
2137:                     // In "Redhawk" we can write this sort of code directly as well. However, we should
2138:                     // never have a case where the value of the assignment is "used", either in our own
2139:                     // lowering passes or in Redhawk. We never have something like:
2140:                     //
2141:                     // ref int t1 = (ref int t2 = ref M().s); 
2142:                     //
2143:                     // or the even more odd:
2144:                     //
2145:                     // int t1 = (ref int t2 = ref M().s);
2146:                     //
2147:                     // Therefore we don't have to worry about what if the temporary value we are stashing
2148:                     // away is of ref type.
2149:                     //
2150:                     // If we ever do implement this sort of feature then we will need to figure out which
2151:                     // of the situations above we are in, and ensure that the correct kind of temporary
2152:                     // is created here. And also that either its value or its indirected value is read out
2153:                     // after the store, in EmitAssignmentPostfix, below.
2154: 
2155:                     Debug.Assert(assignmentOperator.RefKind == RefKind.None);
2156: 
2157:                     temp = AllocateTemp(assignmentOperator.Left.Type, assignmentOperator.Left.Syntax);
2158:                     _builder.EmitLocalStore(temp);
